import SwiftUI

/// About: icon, name, version, *by Etzian*, copyright, third-party licences and the legal documents
/// bundled with the app (generated by `ez legal gen .`; a document not generated yet is not listed).
struct AboutView: View {
    var body: some View {
        List {
            Section {
                VStack(spacing: EZ.Space.xs) {
                    Image(systemName: "doc.viewfinder")
                        .font(.largeTitle)
                        .foregroundStyle(.tint)
                        .frame(minWidth: Metrics.minTouchTarget, minHeight: Metrics.minTouchTarget)
                        .accessibilityHidden(true)
                    Text(AppInfo.name).font(.title2.bold())
                    Text(AppInfo.endorsement).foregroundStyle(.secondary)
                    Text("about.version \(AppInfo.version)").font(.footnote).foregroundStyle(.secondary)
                }
                .frame(maxWidth: .infinity)
                .accessibilityElement(children: .combine)
            }
            Section {
                ForEach(LegalDocument.bundled) { doc in
                    NavigationLink(doc.title) { DocumentView(title: doc.title, url: doc.url) }
                }
                if let licences = Bundle.main.url(forResource: "THIRD-PARTY", withExtension: "md") {
                    NavigationLink("about.licences") { DocumentView(title: "about.licences", url: licences) }
                }
            }
            Section {
                Text(verbatim: AppInfo.copyright)
                Text(verbatim: Company.jurisdiction).foregroundStyle(.secondary)
                if !Company.supportEmail.isEmpty, let mail = URL(string: "mailto:\(Company.supportEmail)") {
                    Link(destination: mail) { LabeledContent("about.contact") { Text(verbatim: Company.supportEmail) } }
                }
            }
            .font(.footnote)
        }
        .navigationTitle(Text("settings.about"))
    }
}

/// A legal document generated into `legal/generated/` and bundled, in the user's language.
struct LegalDocument: Identifiable {
    let id: String
    let title: LocalizedStringKey
    let url: URL

    static var bundled: [LegalDocument] {
        let lang = Locale.current.language.languageCode?.identifier == "fr" ? "fr-CA" : "en"
        let docs: [(String, LocalizedStringKey)] = [("privacy-policy", "about.privacyPolicy"), ("terms", "about.terms"),
                                                    ("eula", "about.eula")]
        return docs.compactMap { name, title in
            (Bundle.main.url(forResource: "\(name).\(lang)", withExtension: "md")
                ?? Bundle.main.url(forResource: name, withExtension: "md")).map { LegalDocument(id: name, title: title, url: $0) }
        }
    }
}

/// A bundled Markdown document, rendered.
struct DocumentView: View {
    let title: LocalizedStringKey
    let url: URL

    var body: some View {
        ScrollView {
            Text(content)
                .textSelection(.enabled)
                .padding(EZ.Space.md)
                .frame(maxWidth: .infinity, alignment: .leading)
        }
        .navigationTitle(Text(title))
        .navigationBarTitleDisplayMode(.inline)
    }

    private var content: AttributedString {
        let text = (try? String(contentsOf: url, encoding: .utf8)) ?? ""
        return (try? AttributedString(markdown: text, options: .init(interpretedSyntax: .inlineOnlyPreservingWhitespace)))
            ?? AttributedString(text)
    }
}
